#include <cassert>
#include <cstddef>
#include <iostream>
#include <map>
#include <vector>
struct Node { int value; Node* next; };
Node* KeepOnlySingleOccurrences(Node* head) {
    std::map<int, std::size_t> counts;
    for (Node* p = head; p != nullptr; p = p->next) ++counts[p->value];
    Node* result = nullptr;
    Node* tail = nullptr;
    while (head != nullptr) {
        Node* saved = head->next; // 연결 변경 전에 아직 읽지 않은 위치를 보존합니다.
        if (counts.at(head->value) == 1) {
            head->next = nullptr;
            if (tail != nullptr) tail->next = head;
            else result = head;
            tail = head;
        }
        head = saved;
    }
    return result; // 제외한 노드의 해제 책임은 호출자에게 남습니다.
}
int main() {
    std::size_t cases = 0;
    std::size_t combinations = 1;
    for (std::size_t n = 0; n <= 8; ++n) {
        if (n != 0) combinations *= 3;
        for (std::size_t pattern = 0; pattern < combinations; ++pattern) {
            std::vector<Node> nodes(n);
            std::size_t code = pattern;
            for (std::size_t i = 0; i < n; ++i) {
                nodes[i].value = static_cast<int>(code % 3) - 1;
                code /= 3;
                nodes[i].next = (i + 1 < n) ? &nodes[i + 1] : nullptr;
            }
            std::vector<Node*> expected;
            // 다른 위치와 직접 비교하는 독립 참조 판정입니다.
            for (std::size_t i = 0; i < n; ++i) {
                std::size_t count = 0;
                for (std::size_t j = 0; j < n; ++j)
                    if (nodes[i].value == nodes[j].value) ++count;
                if (count == 1) expected.push_back(&nodes[i]);
            }
            Node* p = KeepOnlySingleOccurrences(n ? &nodes[0] : nullptr);
            for (Node* wanted : expected) { assert(p == wanted); p = p->next; }
            assert(p == nullptr); ++cases;
        }
    }
    std::cout << "linked-list cases: " << cases << ", address/order preservation: passed\n";
}
